arguments.command:
cd /workspace && python3 - <<'PYEOF'
old_low = """inline uint64_t low_mask(int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (~0ULL << (64 - len));
}"""
new_low = """inline uint64_t low_mask(int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (1ULL << len) - 1;
}"""
for p in ('src/image_build.cpp','src/image.cpp'):
    s=open(p).read()
    assert old_low in s, p
    s=s.replace(old_low,new_low)
    open(p,'w').write(s)
PYEOF
grep -n "low_mask\|top_mask\|mask_top" src/image_build.cpp src/image.cpp src/fib.cpp | head -30
